-- Authoritative operational AI knowledge for common PowerHub workflows.
insert into public.chat_knowledge_articles
(title,primary_question,alternative_questions,answer,category,linked_route,related_operation,status,search_aliases,audience,source,version,published_at,created_by_user_id,updated_by_user_id)
select * from (values
('كيف أحذف أو أوقف مشتركًا','كيف أحذف مشترك؟','["حذف مشترك","إزالة مشترك","إلغاء مشترك","تعطيل مشترك"]'::jsonb,'تعامل مع المشترك من قسم المشتركين وفق الإجراءات المتاحة للحساب والصلاحيات. لا تحذف سجلًا إذا كان النظام يعرض بدلًا منه إجراء إيقاف أو تعطيل أو إلغاء؛ استخدم الإجراء الذي يظهره النظام لأن السجل قد يكون مرتبطًا بقراءات وفواتير وتحصيلات. إذا لم يظهر لك إجراء الحذف/الإيقاف أو رفض النظام العملية، راجع الصلاحية وسجل التدقيق أو اطلب من الدعم المراجعة.','subscribers','المشتركين','subscriber_management','published','حذف مشترك,إزالة مشترك,تعطيل مشترك,إلغاء مشترك','generator_owner','powerhub',1,now(),1,1),
('كيف أنشئ فاتورة؟','كيف أعمل فاتورة لمشترك؟','["إنشاء فاتورة","إصدار فاتورة","عمل فاتورة","فاتورة لمشترك"]'::jsonb,'إصدار الفاتورة يتم من المسار المالي بعد توفر القراءة المعتمدة. من قسم المالية والتحصيل اختر إصدار/إنشاء الفاتورة المرتبطة بالقراءة المعتمدة، ثم راجع المبلغ والفترة قبل الاعتماد. في PowerHub لا تُنشأ الفاتورة لمجرد تسجيل القراءة الافتتاحية؛ إصدار الفاتورة مرتبط بمسار القراءة والفوترة المعتمد. بعد الإصدار تظهر الفاتورة في الاستعلامات ويمكن تطبيق مسار إرسالها أو توثيق الدفع بحسب حالتها.','billing','المالية والتحصيل','invoice_create','published','فاتورة,إنشاء فاتورة,إصدار فاتورة,عمل فاتورة','generator_owner','powerhub',1,now(),1,1)
) as v(title,primary_question,alternative_questions,answer,category,linked_route,related_operation,status,search_aliases,audience,source,version,published_at,created_by_user_id,updated_by_user_id)
where not exists (select 1 from public.chat_knowledge_articles a where a.primary_question=v.primary_question);